    anchors = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                anchors[r + c] = grid[r][c]

    # Extend the diagonal bands indicated by the colored diagonal segments.
    # The segments provide a repeating color sequence in order of their
    # diagonal positions.
    sums = sorted(anchors)
    colors = [anchors[s] for s in sums]
    if not colors:
        return [row[:] for row in grid]

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            s = r + c
            # Repeat the anchor sequence, with each anchor marking the start
            # of its corresponding band.
            i = max((i for i, a in enumerate(sums) if a <= s), default=0)
            out[r][c] = colors[i]
    return out
